SELECT (SELECT count(*) FROM composer) AS composer_count, (SELECT count(*) FROM album) AS album_count, (SELECT count(*) FROM track) AS track_count, (SELECT count(*) FROM sqlite_schema WHERE type='index' AND name IN ('track_i1','track_i2')) AS index_count, (SELECT cname FROM composer WHERE cid=12) AS composer_12, (SELECT aname FROM album WHERE aid=104) AS album_104, (SELECT title FROM track WHERE tid=10115) AS track_10115;